import numpy as np

def generate_entries(features, signal_params):
    rsi_length = signal_params['rsi_length']
    pivot_left = signal_params['pivot_left']
    pivot_right = signal_params['pivot_right']
    pivot_offset = signal_params['pivot_offset']
    prior_pivot_occurrence = signal_params['prior_pivot_occurrence']
    n = features.market.size
    long_entries = np.zeros(n, dtype=bool)
    short_entries = np.zeros(n, dtype=bool)
    rsi = features.rsi(rsi_length)
    rsi_pivots = features.pivot_high(pivot_left, pivot_right, rsi)
    if pivot_offset == 0:
        rsi_at_offset = rsi
        high_at_offset = features.market.highs
    else:
        rsi_at_offset = np.full(n, np.nan, dtype=np.float64)
        high_at_offset = np.full(n, np.nan, dtype=np.float64)
        rsi_at_offset[pivot_offset:] = rsi[:-pivot_offset]
        high_at_offset[pivot_offset:] = features.market.highs[:-pivot_offset]
    prior_pivots = []
    for t in range(n):
        if not np.isnan(rsi_pivots[t]):
            occurrence = prior_pivot_occurrence
            if occurrence == 0:
                previous_rsi = rsi_at_offset[t]
                previous_high = high_at_offset[t]
            elif len(prior_pivots) >= occurrence:
                previous_rsi, previous_high = prior_pivots[-occurrence]
            else:
                previous_rsi = np.nan
                previous_high = np.nan
            if np.isfinite(previous_rsi) and np.isfinite(previous_high) and (rsi_at_offset[t] < previous_rsi) and (high_at_offset[t] > previous_high):
                short_entries[t] = True
            prior_pivots.append((rsi_at_offset[t], high_at_offset[t]))
    return (long_entries, short_entries)

def i5_apply_trend_exit(features: object, long_entries: object, short_entries: object, signal_params: dict) -> tuple:
    return features.trend_exit(long_entries, short_entries)

def generate_signals(features, signal_params):
    long_entries, short_entries = generate_entries(features, signal_params)
    long_exits, short_exits = i5_apply_trend_exit(features, long_entries, short_entries, signal_params)
    no_distances = np.full(features.market.size, np.nan, dtype=np.float64)
    return (long_entries, long_exits, short_entries, short_exits, no_distances, no_distances)

